var shaderCanvas, theShader, img;
var cameraPosition;

function preload(){
	shaderCanvas = createGraphics(1112,834, WEBGL);
	theShader = new p5.Shader(shaderCanvas.renderer, vertShader, fragShader);
	//img = loadImage('https://openprocessing.org/sketch/1883622/files/skybox_texture.jpg');
}

function setup() {
	createCanvas(1112, 834);
	background(0);
	cameraPosition = createVector(0,0,5);
	setUniforms();
	//noLoop();
	redraw();
}

function setUniforms(){
	theShader.setUniform("u_resolution", [shaderCanvas.width, shaderCanvas.height]);
	theShader.setUniform("u_origin", [cameraPosition.x, cameraPosition.y, cameraPosition.z]);
	theShader.setUniform("u_density", shaderCanvas.pixelDensity());
	theShader.setUniform("u_time", t);
	theShader.setUniform("u_pp", 2 + sin(t/2));
	//theShader.setUniform("u_cubemap", img);

	shaderCanvas.shader(theShader);
	shaderCanvas.rect(0,0,width,height);
}

var t = 0;
var dt = 0.03;
var pauseAnimation = false;

function draw() {
	var cameraChanged = updateCamera();
	if (pauseAnimation && !cameraChanged)
		return;
	if (!pauseAnimation)
		t+=dt;
	setUniforms();
	ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 20, 20);
	image(shaderCanvas,0,0);
}

function keyPressed(){
	if (key=='p')
		pauseAnimation = !pauseAnimation;
}

// save jpg
