// === Tab: camera ===
var dZoom = 1.05;
var dAngle = Math.PI/100;

var PLUS = 107;
var MINUS = 109;

function cameraKeyPressed(){
	var cameraChanged = false;
	if (keyIsDown(PLUS)){
		// zoom in
		cameraRadius /= dZoom;
		cameraChanged = true;
	}
	if (keyIsDown(MINUS)){
		// zoom out
		cameraRadius *= dZoom;
		cameraChanged = true;
	}
	if (keyIsDown(RIGHT_ARROW)){
		horizontalAngle -= dAngle;
		cameraChanged = true;
	}
	if (keyIsDown(LEFT_ARROW)){
		horizontalAngle += dAngle;
		cameraChanged = true;
	}
	if (keyIsDown(UP_ARROW)){
		verticalAngle += dAngle;
		if (verticalAngle>=Math.PI/2)
			verticalAngle=Math.PI/2;
		cameraChanged = true;
	}
	if (keyIsDown(DOWN_ARROW)){
		verticalAngle -= dAngle;
		if (verticalAngle<=-Math.PI/2)
			verticalAngle=-Math.PI/2;
		cameraChanged = true;
	}
	return cameraChanged;
}

var cameraRadius = 2;  // radius must be nonnegative
var horizontalAngle = Math.PI/5; // between 0 and 2PI (or everything...)
var verticalAngle = Math.PI/7; // between -PI/2 to PI/2

function updateCamera(){
	/*camera(
		posX, posY, posZ,
		lookAtX, lookAtY, lookAtY,
		upX, upY, upZ
		);*/

	var cameraChanged = cameraKeyPressed();

	cameraPosition.set(
		cameraRadius*Math.cos(verticalAngle)*Math.sin(horizontalAngle),
		cameraRadius*Math.sin(verticalAngle),
		cameraRadius*Math.cos(verticalAngle)*Math.cos(horizontalAngle)
		);

	return cameraChanged;

}

