// === Tab: shader noise ===
let shaderNoise = `
// Some useful functions
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

//
// Description : GLSL 2D simplex noise function
//      Author : Ian McEwan, Ashima Arts
//  Maintainer : ijm
//     Lastmod : 20110822 (ijm)
//     License :
//  Copyright (C) 2011 Ashima Arts. All rights reserved.
//  Distributed under the MIT License. See LICENSE file.
//  https://github.com/ashima/webgl-noise
//
float noise(vec2 v) {

    // Precompute values for skewed triangular grid
    const vec4 C = vec4(0.211324865405187,
                        // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,
                        // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,
                        // -1.0 + 2.0 * C.x
                        0.024390243902439);
                        // 1.0 / 41.0

    // First corner (x0)
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);

    // Other two corners (x1, x2)
    vec2 i1 = vec2(0.0);
    i1 = (x0.x > x0.y)? vec2(1.0, 0.0):vec2(0.0, 1.0);
    vec2 x1 = x0.xy + C.xx - i1;
    vec2 x2 = x0.xy + C.zz;

    // Do some permutations to avoid
    // truncation effects in permutation
    i = mod289(i);
    vec3 p = permute(
            permute( i.y + vec3(0.0, i1.y, 1.0))
                + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(
                        dot(x0,x0),
                        dot(x1,x1),
                        dot(x2,x2)
                        ), 0.0);

    m = m*m ;
    m = m*m ;

    // Gradients:
    //  41 pts uniformly over a line, mapped onto a diamond
    //  The ring size 17*17 = 289 is close to a multiple
    //      of 41 (41*7 = 287)

    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;

    // Normalise gradients implicitly by scaling m
    // Approximation of: m *= inversesqrt(a0*a0 + h*h);
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0+h*h);

    // Compute final noise value at P
    vec3 g = vec3(0.0);
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * vec2(x1.x,x2.x) + h.yz * vec2(x1.y,x2.y);
    return 130.0 * dot(m, g);
}

`

// === Tab: frag shader ===
let fragShader = `
#ifdef GL_ES 
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_density;
uniform float u_time;
uniform vec3 u_origin;
uniform sampler2D u_cubemap;
uniform float u_pp;

const float PI = 3.1415926535;
` +
shaderNoise

+ `

// ------------------------------- rotations -------------------------------

mat3 rotateX(float angle){
	return mat3(
		1., 0., 0.,
		0., cos(angle),  sin(angle),
		0., -sin(angle), cos(angle)
	);
}

mat3 rotateY(float angle){
	return mat3(
		cos(angle), 0., sin(angle),
		0., 1.,  0.,
		-sin(angle), 0., cos(angle)
	);
}

mat3 rotateZ(float angle){
	return mat3(
		cos(angle),  sin(angle), 0., 
		-sin(angle), cos(angle), 0., 
		0., 0., 1.
	);
}

struct AffineMap {
	mat3 linear;
	vec3 translation;
};

vec3 apply(AffineMap map, vec3 p){
	return map.linear*(p-map.translation);
}

// ============================== Material ==============================

struct Material {
	vec3 color;
	float reflectionFactor;
};

const Material RedMaterial = Material(vec3(1.,0.,0.), 0.03);
var Material GreenMaterial = Material(vec3(0.,1.,0.), 0.3);
var Material BlueMaterial = Material(vec3(0.,0.,1.), 0.3);
var Material GrayMaterial = Material(vec3(0.3), 0.3);
var Material BlackMaterial = Material(vec3(0.0), 0.);

// ============================== Objects ==============================

const float MAX_DIST = 1000000.;
struct RayInfo {
	float d;
	Material material;
};

RayInfo minDistance(RayInfo info1, RayInfo info2){
	if (info1.d<info2.d)
		return info1;
	return info2;
}

// ------------------------------- sphere -------------------------------

// A sphere of radius r centered around the origin
struct Sphere {
	float r;
	Material material;
};

RayInfo distSphere(vec3 pt, Sphere sphere){
	float sum = dot(pow(abs(pt), vec3(u_pp)), vec3(1.));
	float d = (pow(sum, 1./u_pp) - sphere.r);
	d = pow(pow(abs(pt.x),1.5) + pow(abs(pt.y),1.5) + pow(abs(pt.z),1.5), 1./1.5);
	d = abs(pt.x) + abs(pt.y) + abs(pt.z);
	return RayInfo(d*0.9, sphere.material);
	//return RayInfo(length(p) - sphere.r, sphere.material);
}


// ============================== Scene ==============================

const float torusR = 0.2;
const float outerR = 2.;
const float innerR = 1.;
const float sphereR = innerR - torusR*2.;

const Sphere sphere = Sphere(
	sphereR, Material(vec3(1,0.3,0), 0.3)
);

RayInfo distScene(vec3 pt){
	RayInfo background = RayInfo(MAX_DIST, BlackMaterial);

	float sum = dot(pow(abs(pt), vec3(u_pp)), vec3(1.));
	RayInfo pSphere = RayInfo((pow(sum, 1./u_pp) - sphere.r)*0.5, sphere.material);

	return minDistance(background, pSphere);
}

// ============================ Ray March ============================

const float MIN_DEPTH = 0.001;

/**
 * Look for the next intersection of the given ray with the scene.
 */
RayInfo simpleRayMarch(vec3 origin, vec3 direction, float start, float end) {
	RayInfo info;
  float depth = start;

  for (int i = 0; i < 255; i++) {
    vec3 p = origin + depth * direction;
    info = distScene(p);
    depth += info.d;
    if (info.d < MIN_DEPTH || depth > end) break;
  }
	if (depth > end)
		 return RayInfo(MAX_DIST, Material(vec3(0.8),0.));

  return RayInfo(depth, info.material);
}

vec3 calcNormal(vec3 p) {
  vec2 e = vec2(1.0, -1.0) * 0.0005; // epsilon
  float r = 1.; // radius of sphere
  return normalize(
    e.xyy * distScene(p + e.xyy).d +
    e.yyx * distScene(p + e.yyx).d +
    e.yxy * distScene(p + e.yxy).d +
    e.xxx * distScene(p + e.xxx).d);
}


// ============================ Light ============================

struct Light {
	vec3 position;

	float ambientFactor;
	vec3 ambientColor;

	float diffuseFactor;
	vec3 diffuseColor;

	float specularFactor;
	float specularAlpha;
	vec3 specularColor;
};

/**
 * Compute the light effect at the given point.
 */
vec3 phong(vec3 p, vec3 normal, vec3 rayDirection, Light light) {

	vec3 lightDir = normalize(p-light.position);

  // ambient
  vec3 ambient = light.ambientFactor * light.ambientColor;

  // diffuse
  float dotLN = clamp(-dot(lightDir, normal), 0., 1.);
  vec3 diffuse = light.diffuseFactor * dotLN * light.diffuseColor;

  // specular
  float dotRV = clamp(dot(reflect(lightDir, normal), -rayDirection), 0., 1.);
  vec3 specular = light.specularFactor * pow(dotRV, light.specularAlpha) * light.specularColor;

  return ambient + diffuse + specular;
}

const Light light1 = Light(
	vec3(5., 2., 4.),
	0.3, vec3(0.7, 0.7, 0.7),
	1., vec3(1),
	0.6, 10., vec3(1)
);

var Light light2 = Light(
	vec3(-5., -4., -2.),
	0.0, vec3(0.7, 0.7, 0),
	1., vec3(0,1,1),
	0.9, 1., vec3(0.2,0.8,0.9)
);

// ============================ Main ============================

const int reflectionSteps = 4;
const float BUMP_STRENGTH = 0.1;
const float BUMP_DETAILS = 3.;

/**
 * Look for the next intersection of the given ray with the scene, and if needed add reflections.
 */
vec4 rayMarch(vec3 origin, vec3 direction, float start, float end) {
	RayInfo info;
	vec3 p = origin;
	float factor = 1.;
	vec3 color = vec3(0.);
	float depth = start;

	info = simpleRayMarch(p, direction, start, end);
	p = origin + direction * info.d; 
	vec3 normal = calcNormal(p);

	// add "bumps" to the normal to create some details on the object
	normal.x += BUMP_STRENGTH*noise(BUMP_DETAILS*p.yz);
	normal.y += BUMP_STRENGTH*noise(BUMP_DETAILS*p.xz);
	normal.z += BUMP_STRENGTH*noise(BUMP_DETAILS*p.yx);

	vec3 lightColor1 = phong(p, normal, direction, light1);
	vec3 lightColor2 = phong(p, normal, direction, light2);
	color = 1.5*(1.-info.material.reflectionFactor)*(info.material.color + lightColor1 + lightColor2)/2.;

	return vec4(color, depth);
}

void main() {		
	vec2 uv = (gl_FragCoord.xy/u_density-u_resolution/2.)/u_resolution.y;

  vec3 origin = u_origin;
	vec3 forward = normalize(origin);
	vec3 up = vec3(0., 1., 0.);
	vec3 right = normalize(cross(forward, up));
	up = -normalize(cross(origin, right));
  vec3 direction = normalize(uv.x * right + uv.y * up - normalize(origin));

	vec4 result = rayMarch(origin, direction, 0., 100.); 
	float depth = result.w;
	vec3 color = result.rgb;

	gl_FragColor = vec4(color,1.0);  		    
}
`

